use crate::geometry::Point;

const EPSILON: f64 = 1e-12;

#[derive(Clone, Debug)]
struct Node {
    point: Point,
    original_index: u32,
    prev: usize,
    next: usize,
    removed: bool,
}

pub fn earcut(polygon: &[Vec<Point>]) -> Vec<u32> {
    let Some(ring) = polygon.first() else {
        return Vec::new();
    };

    if ring.len() < 3 {
        return Vec::new();
    }

    let mut nodes = build_nodes(ring);
    let mut remaining = nodes.len();
    let mut ear = nodes.len() - 1;
    let mut triangles = Vec::with_capacity((ring.len().saturating_sub(2)) * 3);
    let orientation = signed_area(ring).signum();
    let polygon_sign = if orientation >= 0.0 { 1.0 } else { -1.0 };
    let mut misses = 0usize;

    while remaining > 2 {
        let prev = nodes[ear].prev;
        let next = nodes[ear].next;

        if remaining == 3 {
            triangles.push(nodes[prev].original_index);
            triangles.push(nodes[ear].original_index);
            triangles.push(nodes[next].original_index);
            break;
        }

        if is_ear(ear, &nodes, polygon_sign) {
            triangles.push(nodes[prev].original_index);
            triangles.push(nodes[ear].original_index);
            triangles.push(nodes[next].original_index);

            nodes[prev].next = next;
            nodes[next].prev = prev;
            nodes[ear].removed = true;
            remaining -= 1;

            ear = nodes[next].next;
            misses = 0;
        } else {
            ear = next;
            misses += 1;

            if misses > remaining {
                break;
            }
        }
    }

    triangles
}

fn build_nodes(ring: &[Point]) -> Vec<Node> {
    let len = ring.len();
    let mut nodes = Vec::with_capacity(len);

    for (index, point) in ring.iter().copied().enumerate() {
        nodes.push(Node {
            point,
            original_index: index as u32,
            prev: if index == 0 { len - 1 } else { index - 1 },
            next: if index + 1 == len { 0 } else { index + 1 },
            removed: false,
        });
    }

    nodes
}

fn signed_area(ring: &[Point]) -> f64 {
    let mut area = 0.0;

    for i in 0..ring.len() {
        let current = ring[i];
        let next = ring[(i + 1) % ring.len()];
        area += current[0] * next[1] - current[1] * next[0];
    }

    area * 0.5
}

fn is_ear(index: usize, nodes: &[Node], polygon_sign: f64) -> bool {
    if nodes[index].removed {
        return false;
    }

    let prev = nodes[index].prev;
    let next = nodes[index].next;
    let a = nodes[prev].point;
    let b = nodes[index].point;
    let c = nodes[next].point;
    let area = triangle_area(a, b, c) * polygon_sign;

    if area <= EPSILON {
        return false;
    }

    let mut cursor = nodes[next].next;
    while cursor != prev {
        if !nodes[cursor].removed && point_in_triangle(nodes[cursor].point, a, b, c, polygon_sign) {
            return false;
        }
        cursor = nodes[cursor].next;
    }

    true
}

fn triangle_area(a: Point, b: Point, c: Point) -> f64 {
    (b[0] - a[0]) * (c[1] - a[1]) - (b[1] - a[1]) * (c[0] - a[0])
}

fn point_in_triangle(p: Point, a: Point, b: Point, c: Point, polygon_sign: f64) -> bool {
    let ab = triangle_area(a, b, p) * polygon_sign;
    let bc = triangle_area(b, c, p) * polygon_sign;
    let ca = triangle_area(c, a, p) * polygon_sign;

    ab >= -EPSILON && bc >= -EPSILON && ca >= -EPSILON
}

#[cfg(test)]
mod tests {
    use super::earcut;
    use crate::geometry::generate_gear_polygon;

    #[test]
    fn matches_reference_example_n5() {
        let polygon = generate_gear_polygon(5);
        assert_eq!(
            earcut(&polygon),
            vec![
                9, 0, 1, 1, 2, 3, 3, 4, 5, 5, 6, 7, 7, 8, 9, 9, 1, 3, 3, 5, 7, 7, 9, 3
            ]
        );
    }

    #[test]
    fn matches_reference_example_n11() {
        let polygon = generate_gear_polygon(11);
        assert_eq!(
            earcut(&polygon),
            vec![
                21, 0, 1, 1, 2, 3, 3, 4, 5, 5, 6, 7, 7, 8, 9, 9, 10, 11, 11, 12, 13, 13, 14,
                15, 15, 16, 17, 17, 18, 19, 19, 20, 21, 21, 1, 3, 3, 5, 7, 7, 9, 11, 11, 13,
                15, 15, 17, 19, 19, 21, 3, 3, 7, 11, 11, 15, 19, 19, 3, 11
            ]
        );
    }
}

